using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using ModelContextProtocol.Server;

namespace McpServer;

[McpServerToolType]
public sealed class WeatherTools
{
    private readonly IHttpClientFactory _httpClientFactory;

    public WeatherTools(IHttpClientFactory httpClientFactory)
    {
        _httpClientFactory = httpClientFactory;
    }

    [McpServerTool, Description("Get current weather for a location by latitude and longitude.")]
    public async Task<string> GetCurrentWeather(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude)
    {
        using var client = _httpClientFactory.CreateClient("WeatherApi");

        var response = await client.GetFromJsonAsync<WeatherResponse>(
            $"v1/forecast?latitude={latitude}&longitude={longitude}&current=temperature_2m,wind_speed_10m");

        if (response?.Current is null)
            return "Weather data unavailable.";

        return $"Temperature: {response.Current.Temperature}°C, " +
               $"Wind speed: {response.Current.WindSpeed} km/h";
    }

    [McpServerTool, Description("Look up coordinates for a city name.")]
    public async Task<string> GeocodeCityName(
        [Description("City name to look up")] string city)
    {
        using var client = _httpClientFactory.CreateClient("WeatherApi");

        var results = await client.GetFromJsonAsync<GeocodingResponse>(
            $"https://geocoding-api.open-meteo.com/v1/search?name={Uri.EscapeDataString(city)}&count=1");

        if (results?.Results is not [var first, ..])
            return $"No results found for '{city}'.";

        return $"{first.Name}: lat={first.Latitude}, lon={first.Longitude}";
    }
}

// --- DTOs ---

public sealed class WeatherResponse
{
    [JsonPropertyName("current")]
    public CurrentWeather? Current { get; set; }
}

public sealed class CurrentWeather
{
    [JsonPropertyName("temperature_2m")]
    public double Temperature { get; set; }

    [JsonPropertyName("wind_speed_10m")]
    public double WindSpeed { get; set; }
}

public sealed class GeocodingResponse
{
    [JsonPropertyName("results")]
    public List<GeocodingResult>? Results { get; set; }
}

public sealed class GeocodingResult
{
    [JsonPropertyName("name")]
    public string Name { get; set; } = "";

    [JsonPropertyName("latitude")]
    public double Latitude { get; set; }

    [JsonPropertyName("longitude")]
    public double Longitude { get; set; }
}

